fn frame(t: i32) {
    let m: i32 = t % 120;
    if m == 0 || m == 60 { host::audio::tone(50, 150, 0); }
    if m == 30 || m == 90 { host::audio::noise(140); }
    if m % 15 == 0 { host::audio::noise(20); }
    host::display::clear(0x101010);
    host::display::draw_string(8, 8, "ROCK BEAT 4/4", 0x808080, 2);
    let mut kc: i32 = 0x302010;
    if m < 8 || (m >= 60 && m < 68) { kc = 0xff8020; }
    let mut sc: i32 = 0x103020;
    if (m >= 30 && m < 38) || (m >= 90 && m < 98) { sc = 0x20ff80; }
    host::display::fill_rect(60, 200, 160, 160, kc);
    host::display::fill_rect(290, 200, 160, 160, sc);
    host::display::draw_string(60, 170, "KICK", 0xffffff, 2);
    host::display::draw_string(290, 170, "SNARE", 0xffffff, 2);
    host::display::present();
}
